def mark_legacy_claims(apps, schema_editor):
    """A 'processing' row left by the poller before retries existed may sit on a
    ticket that version committed before it finished the row. The new poller
    would retry a copy-less 'processing' row, so a re-delivered email could
    become a second ticket. Relabel them; the poller sends those to a person."""
    InboundEmailLog = apps.get_model('core', 'InboundEmailLog')
    InboundEmailLog.objects.filter(status='processing').update(status='needs_review')


